query BlueprintPreview($repo: String!, $branch: String!, $path: String, $ownerId: String, $blueprintId: String) {
  blueprintPreview(
    repo: $repo
    branch: $branch
    path: $path
    ownerId: $ownerId
    blueprintId: $blueprintId
  ) {
    found
    commitId
    error
    reason
    retryable
    validation {
      valid
      errors
      errorDetails {
        code
        line
        column
        path
        error
        __typename
      }
      plan {
        mode
        services
        databases
        keyValue
        envGroups
        syncFalseVars
        totalActions
        actions {
          operation
          kind
          name
          sourcePath
          resourceId
          changedFields {
            path
            __typename
          }
          message
          __typename
        }
        __typename
      }
      estimatedPricing {
        totalUsd
        lines {
          name
          tierLabel
          monthlyUsd
          instanceUsd
          storageUsd
          storageGb
          __typename
        }
        variable {
          name
          reason
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

