const [nameEdited, setNameEdited] = useState(false);
const [branch, setBranch] = useState("");
// A Public Git Branch left behind by a tab switch, bound to its URL: the same
// URL restores it, any other starts blank (w4/331, as w4/240 for services).
const [gitBranchDraft, setGitBranchDraft] = useState<{
  gitUrl: string;
  branch: string;
} | null>(null);
const [path, setPath] = useState("render.yaml");
// The server's refusal awaiting its phrase: a protected environment, or a
// Blueprint takeover that names what it replaces.
const [pendingConfirmation, setPendingConfirmation] =
  useState<BlueprintConfirmationRequired | null>(null);
// sync:false prompt values, keyed by env var name. Secrets: kept only in
// this component's memory until submit, never in router state or URLs.
const [envVarValues, setEnvVarValues] = useState<Record<string, string>>({});

const sourceRepo =
  tab === "github"
    ? (selectedRepo?.cloneUrl ?? "")
    : isValidGitUrl(gitUrl)
      ? gitUrl.trim()
      : "";

const { branches } = useRepoBranches(sourceRepo || null);
const {
  preview,
  loading: previewLoading,
  error: previewError,
  refetch: refetchPreview,
} = useBlueprintPreview(sourceRepo, branch.trim(), path.trim());

// Auto-fill name + branch from the selected source while the user hasn't
// hand-edited the name (same pattern as services.new: the effect reacts to
// selection changes, so a synchronous set is the desired behavior).
useEffect(() => {
  if (tab === "github" && selectedRepo) {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setBranch((b) => b || selectedRepo.defaultBranch);
    if (!nameEdited) {
      setName(repoNameSlug(selectedRepo.fullName));
    }
  } else if (tab === "git" && gitUrl && !nameEdited) {
    const slug = gitUrlSlug(gitUrl);
    if (slug) setName(slug);
  }
}, [tab, selectedRepo, gitUrl, nameEdited]);

const branchOptions = useMemo(
  () => branches.map((b) => ({ value: b, label: b })),
  [branches],
);

const sourceValid = sourceRepo !== "";
// Render parity: Deploy stays disabled until the file fetches + parses. A
// transport-level preview failure does not block — the backend re-validates
// on create anyway.
const previewConflictOnly = isTakeoverOnlyConflict(
  preview?.validation?.errorDetails ?? [],
);
const previewBlocks =
  preview != null &&
  (!preview.found ||
    (preview.validation?.valid !== true && !previewConflictOnly));
const canSubmit =
  sourceValid &&
  branch.trim() !== "" &&
  !busy &&
  !previewLoading &&
  !previewBlocks;

async function handleCreate(confirmation?: string) {
  const suppliedValues = Object.entries(envVarValues)

  useEffect(() => {
    const handle = setTimeout(
      () => setDebounced({ repo, branch, path }),
      DEBOUNCE_MS,
    );
    return () => clearTimeout(handle);
  }, [repo, branch, path]);

  const skip = !debounced.repo || !debounced.branch;
  const { data, loading, error, refetch } = useQuery(BlueprintPreviewDocument, {
    variables: {
      repo: debounced.repo,
      branch: debounced.branch,
      path: debounced.path || null,
      ownerId: currentWorkspaceId,
      blueprintId: forBlueprintId ?? null,
    },
    skip,
    fetchPolicy: "cache-and-network",
    errorPolicy: "all",
  });

  const settled =
    debounced.repo === repo &&
    debounced.branch === branch &&
    debounced.path === path;

  const preview = useMemo(
    () =>
      data?.blueprintPreview
        ? toBlueprintPreviewResult(data.blueprintPreview)
        : null,
    [data],
  );

  // Inputs that just became complete are pending from that very render: the
  // query is still skipped for one debounce, and a caller that read "not
  // loading" then would offer its action before anything was reviewed.
  const awaitingDebounce =
    !settled && (!skip || (repo !== "" && branch !== ""));

  return {
    preview: skip ? null : preview,
    loading: awaitingDebounce || (!skip && loading),
    error,
    refetch,
  };
}

it("restores a Public Git branch when returning to the same URL", async () => {
  previewState.preview = validPreview();
  const user = userEvent.setup();
  renderPage();

  await user.click(await screen.findByRole("tab", { name: /public git/i }));
  await user.type(
    screen.getByLabelText("Repository URL"),
    "https://github.com/acme/public-app",
  );
  await user.type(screen.getByRole("combobox", { name: /branch/i }), "main");
  await user.click(screen.getByRole("tab", { name: /github/i }));
  await user.click(screen.getByRole("tab", { name: /public git/i }));

  expect(screen.getByLabelText("Repository URL")).toHaveValue(
    "https://github.com/acme/public-app",
  );
  expect(screen.getByRole("combobox", { name: /branch/i })).toHaveValue(
    "main",
  );
  const deploy = screen.getByRole("button", { name: /deploy blueprint/i });
  expect(deploy).toBeEnabled();
  await user.click(deploy);
  expect(create).toHaveBeenCalledWith(
    "https://github.com/acme/public-app",
    "main",
    "render.yaml",
    "public-app",
    undefined,
    [],
  );
});

it("does not copy a GitHub repository's branch into the Public Git draft", async () => {
  reposState.repos = [repo()];
  const user = userEvent.setup();
  renderPage();

  // A GitHub selection fills its own default branch…
  await user.click(await screen.findByText("acme/hello-go"));
  expect(screen.getByRole("combobox", { name: /branch/i })).toHaveValue(
    "main",
  );
  // …which Public Git, with no draft of its own, does not inherit.
  await user.click(screen.getByRole("tab", { name: /public git/i }));
  expect(screen.getByRole("combobox", { name: /branch/i })).toHaveValue("");
});

// Paid-only types (workers, private services, cron jobs; ADR030 §7) are not offered Free,
// so the plan grid renders the filtered catalog, the default is its first
// (cheapest paid) tier, and a Free selection made under another service type
// never survives a switch into a paid-only-type submission — an override the current
// type is not offered falls back to the default.
const offeredTypes = offeredInstanceTypes(fields.serviceType, instanceTypes);
const planOverride =
  fields.planOverride != null &&
  offeredTypes.some((it) => it.id === fields.planOverride)
    ? fields.planOverride
    : null;

const form: NewServiceForm = {
  ...fields,
  name: name.name,
  runtime: build.runtime,
  buildCommand: build.buildCommand,
  startCommand: build.startCommand,
  dockerfilePath: build.dockerfilePath,
  plan: planOverride ?? offeredTypes[0]?.id ?? "",
};

// Switching source tab abandons whatever the previous tab had selected —
// except a Public Git Branch, which returning to the same URL restores
// (w4/240); it never carries over to a different repository URL.
const setTab = useCallback(
  (tab: SourceTab) =>
    set((current) => {
      const gitBranchDraft =
        current.tab === "git"
          ? { gitUrl: current.gitUrl, branch: current.branch }
          : current.gitBranchDraft;
      const branch =
        tab === "git" && gitBranchDraft?.gitUrl === current.gitUrl
          ? gitBranchDraft.branch
          : "";
      return { tab, selectedRepo: null, branch, gitBranchDraft };
    }),
  [set],
);

// A static site builds from a Git repo (ADR029) — it has no image source, so
// arriving on Static Site from the Existing Image tab moves the selection
// back to GitHub exactly as a manual tab switch would.
const setServiceType = useCallback(
  (serviceType: ServiceType) =>
    set((current) =>
      serviceType === "static_site" && current.tab === "image"
        ? { serviceType, tab: "github", selectedRepo: null, branch: "" }
        : { serviceType },
    ),
  [set],
);

